="btn btn-default">Kembali</button></form></div></div><script src="../../js/jquery.js"></script><script src="../../js/bootstrap.min.js"></script><script src="../../js/bootstrap-dialog.js"></script><script>$(function(){ $('#batal').click(function(){location.href='pemakai.php';}); $('#simpan').click(function(){var f=$('#formReset')[0];if(!f.checkValidity()){f.reportValidity();return;}$.post('pemakai_simpan.php',$('#formReset').serialize(),function(r){BootstrapDialog.alert({title:r.status==='success'?'Berhasil':'Gagal',type:r.status==='success'?BootstrapDialog.TYPE_SUCCESS:BootstrapDialog.TYPE_DANGER,message:r.message,callback:function(){if(r.status==='success')location.href='pemakai.php';}});},'json');});});</script></body></html>